let idCounter = 0;

/** Generates a compact, time-ordered unique identifier. */
export function generateId(prefix?: string): string {
    idCounter = (idCounter + 1) % 1_679_616; // 36^4
    const timePart = Date.now().toString(36);
    const countPart = idCounter.toString(36).padStart(4, '0');
    const randPart = Math.floor(Math.random() * 46_656)
        .toString(36)
        .padStart(3, '0');
    const core = `${timePart}-${countPart}${randPart}`;
    return prefix ? `${prefix}_${core}` : core;
}

/** Extracts the Unix millisecond timestamp from an ID generated by generateId(). */
export function getIdTimestamp(id: string): number {
    if (!id) {
        return 0;
    }
    const withoutPrefix = id.includes('_') ? id.slice(id.indexOf('_') + 1) : id;
    const dashIdx = withoutPrefix.indexOf('-');
    const timePart = dashIdx !== -1 ? withoutPrefix.slice(0, dashIdx) : withoutPrefix;
    const parsed = Number.parseInt(timePart, 36);
    return Number.isNaN(parsed) ? 0 : parsed;
}
